import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, RenderChildren } from 'claude-code'

import type { Group, HubCounts, HubRow } from '../types'
import {
  age,
  arrange,
  clip,
  countsOf,
  focusUrlIn,
  isAlive,
  newSessionDir,
  parseBeacon,
  parsePs,
  parseRegistered,
  readTail,
  rowFor,
  statusLine,
  tabConfig,
  transcriptPath,
} from './hub'
import type { Beacon, Registered, Transcript } from './hub'

const POLL_MS = 3_000
const LIVENESS_MS = 30_000
const TAIL_BYTES = '262144'
// The hub's own pane, a tab of its own beside the other mods' panes.
const PANE = 'sessions'
const TITLE = 'Sessions'
// The Warp Tab Config `/sessions new` rewrites and opens: ~/.warp/tab_configs/<name>.toml.
const TAB_CONFIG = 'claude_session_hub'
// Sessions the band above the prompt names, at most.
const BAND_MAX = 3

const rowsAtom = atom({ plugin: 'session-hub', key: 'rows' } as const, [])
const countsAtom = atom({ plugin: 'session-hub', key: 'counts' } as const, { needs: 0, turn: 0, working: 0, idle: 0, stale: 0 })
const showStale = atom({ plugin: 'session-hub', key: 'showStale' } as const, false)
const minute = atom({ plugin: 'session-hub', key: 'minute' } as const, 0)

// Theme colours, the same urgency scale the Tasks pane uses: error for what
// needs you now, success for your turn, warning for work under way.
const GROUP_LOOK: Readonly<Record<Group, { title: string; glyph: string; color: string }>> = {
  needs: { title: 'NEEDS YOU', glyph: '!', color: 'error' },
  turn: { title: 'YOUR TURN', glyph: '→', color: 'success' },
  working: { title: 'WORKING', glyph: '◐', color: 'warning' },
  idle: { title: 'IDLE', glyph: '·', color: 'inactive' },
  stale: { title: 'STALE', glyph: '○', color: 'inactive' },
}
// Only these get a full card; the rest are one line.
const isCard = (group: Group) => group === 'needs' || group === 'turn'

// What the poller keeps between ticks. A reload starts these over, and the
// next poll reads everything again.
let home = ''
let thisId = ''
let me: Beacon = { sessionId: '', focusUrl: '', lastInputAt: 0, lastTurnEndAt: 0 }
const records = new Map<string, { mtime: number; record: Registered }>()
const beacons = new Map<string, { mtime: number; beacon: Beacon }>()
const transcripts = new Map<string, { updatedAt: number; transcript: Transcript }>()
const lastStatus = new Map<string, string>()
const seenTurnEnd = new Map<string, number>()
let started = new Map<number, string>()
let checkedAt = 0
let lastRows = ''
let lastCounts = ''
let lastLine = ''
let isPolling = false

const sessionsDir = () => `${home}/.claude/sessions`
const beaconsDir = () => `${home}/.claude/session-hub/beacons`

/** Learns where the files are and which session this is, once per load. */
async function ensureReady($: EngineInterface): Promise<void> {
  if (home) return
  home = (await $.env.get('HOME')) ?? ''
  thisId = await $.session.id()
  me = { ...me, sessionId: thisId, focusUrl: (await $.env.get('WARP_FOCUS_URL')) ?? '' }
  await writeBeacon($)
}

async function writeBeacon($: EngineInterface): Promise<void> {
  if (!home || !me.sessionId) return
  await $.fs.write(`${beaconsDir()}/${me.sessionId}.json`, JSON.stringify(me)).catch(() => undefined)
}

/** Reads the registry files that changed since the last poll. */
async function readRegistry($: EngineInterface): Promise<void> {
  const entries = await $.fs.list(sessionsDir()).catch(() => [])
  const files = entries.filter(entry => entry.kind === 'file' && /^\d+\.json$/.test(entry.name))
  const present = new Set(files.map(file => file.name))
  for (const name of [...records.keys()]) if (!present.has(name)) records.delete(name)
  for (const file of files) {
    if (records.get(file.name)?.mtime === file.mtimeMs) continue
    const record = parseRegistered(await $.fs.read(`${sessionsDir()}/${file.name}`).catch(() => ''))
    // A file caught mid-write keeps its last good record and is read again next poll.
    if (record) records.set(file.name, { mtime: file.mtimeMs, record })
  }
}

async function readBeacons($: EngineInterface): Promise<void> {
  const entries = await $.fs.list(beaconsDir()).catch(() => [])
  for (const entry of entries) {
    if (entry.kind !== 'file' || !entry.name.endsWith('.json')) continue
    const id = entry.name.slice(0, -5)
    if (beacons.get(id)?.mtime === entry.mtimeMs) continue
    const beacon = parseBeacon(await $.fs.read(`${beaconsDir()}/${entry.name}`).catch(() => ''))
    if (beacon) beacons.set(id, { mtime: entry.mtimeMs, beacon })
  }
}

/** Which registered processes are still the ones that registered: one `ps` for all. */
async function checkLiveness($: EngineInterface, now: number): Promise<void> {
  if (now - checkedAt < LIVENESS_MS && checkedAt > 0) return
  const pids = [...records.values()].map(({ record }) => record.pid)
  if (pids.length === 0) return
  const ran = await $.process
    .run(['ps', '-o', 'pid=,lstart=', '-p', pids.join(',')], { env: { TZ: 'UTC', LC_ALL: 'C' } })
    .catch(() => undefined)
  if (!ran) return
  started = parsePs(ran.stdout)
  checkedAt = now
}

/** The end of a session's transcript, read again only when its registry record changed. */
async function transcriptOf($: EngineInterface, record: Registered): Promise<Transcript | undefined> {
  const held = transcripts.get(record.sessionId)
  if (held && held.updatedAt === record.updatedAt) return held.transcript
  const ran = await $.process
    .run(['tail', '-c', TAIL_BYTES, transcriptPath(home, record.cwd, record.sessionId)])
    .catch(() => undefined)
  const transcript = readTail(ran?.stdout ?? '')
  transcripts.set(record.sessionId, { updatedAt: record.updatedAt, transcript })

  return transcript
}

async function poll($: EngineInterface): Promise<void> {
  await ensureReady($)
  if (!home) return
  const now = await $.clock.now()
  await readRegistry($)
  await readBeacons($)
  await checkLiveness($, now)
  const seen = ((await $.store.get('seen')) ?? {}) as Record<string, number>

  const rows: HubRow[] = []
  for (const { record } of records.values()) {
    if (checkedAt > 0 && !isAlive(started, record)) continue
    // A turn this hub watched end, for sessions that write no beacon.
    const before = lastStatus.get(record.sessionId)
    if (before && before !== 'idle' && record.status === 'idle') seenTurnEnd.set(record.sessionId, record.statusUpdatedAt)
    lastStatus.set(record.sessionId, record.status)
    rows.push(
      rowFor({
        record,
        transcript: await transcriptOf($, record),
        beacon: beacons.get(record.sessionId)?.beacon,
        seenTurnEnd: seenTurnEnd.get(record.sessionId) ?? 0,
        seenAt: seen[record.sessionId] ?? 0,
        thisSessionId: thisId,
        now,
      }),
    )
  }

  // This session is the one you are in, so it is left out of its own list.
  const arranged = arrange(rows).filter(row => !row.isThis)
  const rowsJson = JSON.stringify(arranged)
  if (rowsJson !== lastRows) {
    lastRows = rowsJson
    await update($, rowsAtom, () => arranged)
  }
  const counts: HubCounts = countsOf(arranged)
  const countsJson = JSON.stringify(counts)
  if (countsJson !== lastCounts) {
    lastCounts = countsJson
    await update($, countsAtom, () => counts)
  }
  const line = statusLine(counts)
  if (line !== lastLine) {
    lastLine = line
    $.ui.status(line || undefined)
  }
  const thisMinute = Math.floor(now / 60_000)
  if ((await read($, minute)) !== thisMinute) await update($, minute, () => thisMinute)
}

function pollSoon($: EngineInterface): Promise<void> {
  if (isPolling) return Promise.resolve()
  isPolling = true
  return poll($)
    .catch(error => $.ui.log(`session-hub: poll failed: ${String(error)}`, { to: 'debug' }))
    .finally(() => {
      isPolling = false
    })
}

/**
 * Jumps to a session's Warp pane. Its beacon has the link; for a session that
 * started before the hub, the link is read from that one process's environment
 * when you press, and nothing else from it is kept. Failing that, it says where
 * the session is.
 */
async function jump($: EngineInterface, row: HubRow): Promise<void> {
  const seen = ((await $.store.get('seen')) ?? {}) as Record<string, number>
  seen[row.sessionId] = await $.clock.now()
  await $.store.set('seen', seen)

  let url = row.focusUrl
  if (!url && !row.isDesktop) {
    const ran = await $.process.run(['ps', '-E', '-p', String(row.pid), '-o', 'command=']).catch(() => undefined)
    url = focusUrlIn(ran?.stdout ?? '')
  }
  const opened = url ? await $.process.run(['open', url]).catch(() => undefined) : undefined
  if (!opened || opened.exitCode !== 0) {
    $.ui.toast(
      row.isDesktop ? `"${row.title}" is in Claude Desktop.` : `No jump link for "${row.title}": it is in ${row.cwd}.`,
    )
  }
  await pollSoon($)
}

/**
 * Opens a new Warp tab running `claude` in `args` (a path, `~` allowed), or
 * this session's directory. Warp only runs a command in a new tab from a Tab
 * Config, so the hub rewrites its own one and opens it by name.
 */
async function startNew($: EngineInterface, args: string): Promise<string> {
  await ensureReady($)
  const dir = newSessionDir(args, home, await $.session.cwd())
  await $.fs.write(`${home}/.warp/tab_configs/${TAB_CONFIG}.toml`, tabConfig(dir))
  const opened = await $.process.run(['open', `warp://tab_config/${TAB_CONFIG}`]).catch(() => undefined)
  if (!opened || opened.exitCode !== 0) {
    const said = `Couldn't open Warp for a new session in ${dir}.`
    $.ui.toast(said)
    return said
  }

  return `New Claude session opening in Warp, in ${dir}.`
}

const listedOf = async ($: EngineInterface): Promise<HubRow[]> => {
  const rows = await read($, rowsAtom)
  return (await read($, showStale)) ? rows : rows.filter(row => row.group !== 'stale')
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    await ensureReady($)
    await $.command.register({
      name: 'sessions',
      description: 'Focus the sessions pane, jump to one (/sessions 3), or start one (/sessions new [dir])',
      argumentHint: '[number | new [dir]]',
    })
    void pollSoon($)
    $.clock.every(POLL_MS, () => void pollSoon($))
    void $.ui.open({ id: PANE, title: TITLE })

    return started
  })

  // `/sessions` opens the pane with the keyboard on the first session, so
  // 1-9 or Tab and Enter work at once; `/sessions 3` jumps straight to the third.
  on('command.run', { command: 'sessions' }, async ($, e) => {
    const asked = /^new\b\s*(.*)$/.exec(e.args.trim())
    if (asked) return { text: await startNew($, asked[1] ?? '') }
    await pollSoon($)
    const listed = await listedOf($)
    const picked = /^\d+$/.test(e.args.trim()) ? listed[Number(e.args.trim()) - 1] : undefined
    if (picked) {
      await jump($, picked)
      return { text: `Jumped to ${picked.title}.` }
    }

    await $.ui.open({ id: PANE, title: TITLE, focus: true }).catch(() => undefined)
    const first = listed[0]
    if (first) void $.ui.focus({ requestId: PANE, key: `session-${first.sessionId}` }).catch(() => undefined)
    const counts = await read($, countsAtom)

    return { text: statusLine(counts) || 'No other sessions are open.' }
  })

  // This session's beacon: when you last typed here, and when its last turn ended.
  on('prompt.submit', async ($, e, next) => {
    await ensureReady($)
    me = { ...me, lastInputAt: await $.clock.now() }
    void writeBeacon($)

    return next(e)
  }).catch(($, e, next) => next(e))

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    if ((e as { agentId?: unknown }).agentId === undefined) {
      await ensureReady($)
      me = { ...me, lastTurnEndAt: await $.clock.now() }
      void writeBeacon($)
    }

    return done
  })

  // 'sessions' is PANE, written out so `claude plugin validate` can read the matcher.
  // Sessions that need you or have answered get a card; the rest are one line.
  // The pane scrolls, so nothing is cut to fit.
  on('ui.render', { component: 'Pane', requestId: 'sessions' }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const rows = await read($, rowsAtom)
    const isStaleShown = await read($, showStale)
    await read($, minute)
    const now = await $.clock.now()
    const width = Math.max(30, e.props.bodyColumns)

    const shown = rows.filter(row => row.group !== 'stale' || isStaleShown)
    const staleCount = rows.filter(row => row.group === 'stale').length
    const lines: RenderChildren[] = []
    let group: Group | undefined
    shown.forEach((row, index) => {
      const look = GROUP_LOOK[row.group]
      const hasCard = isCard(row.group)
      if (row.group !== group) {
        if (group !== undefined) lines.push(<Text> </Text>)
        group = row.group
        lines.push(
          <Text bold color={look.color}>
            {look.title}
          </Text>,
        )
      }
      const when = age(now - row.since)
      const place = hasCard ? '' : row.isDesktop ? 'Desktop' : row.project
      const room = Math.max(8, width - when.length - 6 - (place ? place.length + 3 : 0))
      lines.push(
        <Box flexDirection="row" justifyContent="space-between">
          <Button
            key={`session-${row.sessionId}`}
            plain
            hotkey={index < 9 ? String(index + 1) : undefined}
            dimColor={row.group === 'stale'}
            onPress={() => jump($, row)}
          >
            <Text color={look.color}>{look.glyph}</Text> <Text bold={hasCard}>{clip(row.title, room)}</Text>
            {place !== '' && <Text dimColor> · {place}</Text>}
          </Button>
          <Text dimColor>{when}</Text>
        </Box>,
      )
      const pad = 5
      if (hasCard) {
        const where = [row.isDesktop ? 'Desktop' : row.project, row.branch, row.engine].filter(Boolean).join(' · ')
        lines.push(
          <Box flexDirection="column" paddingLeft={pad}>
            <Text dimColor wrap="truncate-end">
              {where}
            </Text>
            {row.reason !== '' && (
              <Text color={look.color} wrap="wrap">
                {clip(row.reason, (width - pad) * 2)}
              </Text>
            )}
            {row.prompt !== '' && (
              <Text dimColor wrap="truncate-end">
                you: {row.prompt}
              </Text>
            )}
          </Box>,
        )
      } else if (row.group === 'working' && row.reason !== 'working') {
        // What a working session last said, so you can tell them apart.
        lines.push(
          <Box paddingLeft={pad}>
            <Text dimColor wrap="truncate-end">
              {row.reason}
            </Text>
          </Box>,
        )
      }
    })
    if (staleCount > 0) {
      lines.push(
        <Button key="sessions-stale" plain dimColor onPress={() => update($, showStale, isNow => !isNow)}>
          {isStaleShown ? `hide ${staleCount} stale` : `+ ${staleCount} stale (idle over 3 days)`}
        </Button>,
      )
    }
    if (rows.length === 0) lines.push(<Text dimColor>No other sessions open.</Text>)

    return (
      <Box flexDirection="column">
        {lines}
        <Text> </Text>
        <Box flexDirection="row" gap={2}>
          <Button key="sessions-new" plain hotkey="n" onPress={() => void startNew($, '')}>
            New session here
          </Button>
          <Text dimColor>1-9 jump · /sessions new [dir]</Text>
        </Box>
      </Box>
    )
  })

  // A line above the prompt naming the sessions that need you or have
  // answered, each one press from a jump: click it, or ctrl+x tab then Tab and
  // Enter. Digit hotkeys are left off: a bare digit in an empty prompt would
  // press them. It sits above whatever another plugin draws in the band.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const waiting = (await read($, rowsAtom)).filter(row => isCard(row.group))
    if (waiting.length === 0) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    const each = Math.max(10, Math.floor((e.props.bodyColumns - 12) / Math.min(BAND_MAX, waiting.length)) - 5)
    const mine = (
      <Box flexDirection="row" gap={2}>
        <Text dimColor>sessions</Text>
        {waiting.slice(0, BAND_MAX).map(row => (
          <Button key={`band-${row.sessionId}`} plain onPress={() => jump($, row)}>
            <Text color={GROUP_LOOK[row.group].color}>{GROUP_LOOK[row.group].glyph}</Text> {clip(row.title, each)}
          </Button>
        ))}
        {waiting.length > BAND_MAX && <Text dimColor>+{waiting.length - BAND_MAX}</Text>}
      </Box>
    )
    const below = await next(e)

    return below.type === 'engine' ? mine : (
      <Box flexDirection="column">
        {mine}
        {below}
      </Box>
    )
  })
}

