import type { Group, HubCounts, HubRow } from '../types'

// The session hub's logic, kept free of `$` so it can be tested: reading the
// engine's session registry (~/.claude/sessions/<pid>.json), reading the end of
// a session's transcript, and placing each session in the queue.

export const STALE_MS = 3 * 24 * 60 * 60 * 1000

/** A registry record: one session the engine says is open. */
export type Registered = {
  pid: number
  sessionId: string
  cwd: string
  name: string
  nameSource: string
  kind: string
  entrypoint: string
  status: string
  waitingFor: string | null
  statusUpdatedAt: number
  updatedAt: number
  procStart: string
}

/** What a session writes about itself for the hubs in other sessions to read. */
export type Beacon = { sessionId: string; focusUrl: string; lastInputAt: number; lastTurnEndAt: number }

const text = (value: unknown) => (typeof value === 'string' ? value : '')
const count = (value: unknown) => (typeof value === 'number' && Number.isFinite(value) ? value : 0)

/**
 * A registry file's record, or null for one that is not an open session: a
 * pre-warmed spare, a parked job, a daemon, or a file read halfway through a
 * write (which the next poll reads again).
 */
export function parseRegistered(json: string): Registered | null {
  let raw: Record<string, unknown>
  try {
    raw = JSON.parse(json) as Record<string, unknown>
  } catch {
    return null
  }
  const kind = text(raw.kind)
  if (kind !== 'interactive' && kind !== 'bg') return null
  if (raw.spare === true || raw.parkedJobId) return null
  const sessionId = text(raw.sessionId)
  const pid = count(raw.pid)
  if (!sessionId || pid <= 0) return null

  return {
    pid,
    sessionId,
    cwd: text(raw.cwd),
    name: text(raw.name),
    nameSource: text(raw.nameSource),
    kind,
    entrypoint: text(raw.entrypoint),
    status: text(raw.status),
    waitingFor: typeof raw.waitingFor === 'string' ? raw.waitingFor : null,
    statusUpdatedAt: count(raw.statusUpdatedAt) || count(raw.updatedAt),
    updatedAt: count(raw.updatedAt),
    procStart: text(raw.procStart),
  }
}

export function parseBeacon(json: string): Beacon | null {
  try {
    const raw = JSON.parse(json) as Record<string, unknown>
    const sessionId = text(raw.sessionId)
    if (!sessionId) return null
    return { sessionId, focusUrl: text(raw.focusUrl), lastInputAt: count(raw.lastInputAt), lastTurnEndAt: count(raw.lastTurnEndAt) }
  } catch {
    return null
  }
}

/** Where the engine keeps a session's transcript. */
export function transcriptPath(home: string, cwd: string, sessionId: string): string {
  return `${home}/.claude/projects/${cwd.replace(/[^a-zA-Z0-9]/g, '-')}/${sessionId}.jsonl`
}

export type Transcript = {
  customTitle: string
  aiTitle: string
  branch: string
  model: string
  effort: string
  recap: string
  lastReply: string
  lastPrompt: string
}

const EMPTY: Transcript = { customTitle: '', aiTitle: '', branch: '', model: '', effort: '', recap: '', lastReply: '', lastPrompt: '' }

/**
 * What the end of a transcript says, the newest record of each kind winning.
 * The first line of a cut tail is a fragment and parses to nothing.
 */
export function readTail(tail: string): Transcript {
  const found = { ...EMPTY }
  for (const line of tail.split('\n')) {
    if (!line.startsWith('{')) continue
    let record: Record<string, unknown>
    try {
      record = JSON.parse(line) as Record<string, unknown>
    } catch {
      continue
    }
    switch (record.type) {
      case 'custom-title':
        found.customTitle = text(record.customTitle) || found.customTitle
        break
      case 'ai-title':
        found.aiTitle = text(record.aiTitle) || found.aiTitle
        break
      case 'last-prompt':
        found.lastPrompt = text(record.lastPrompt) || found.lastPrompt
        break
      case 'system':
        if (record.subtype === 'away_summary') found.recap = text(record.content) || found.recap
        break
      case 'assistant': {
        const message = (record.message ?? {}) as { model?: unknown; content?: unknown }
        found.branch = text(record.gitBranch) || found.branch
        found.model = text(message.model) || found.model
        found.effort = text(record.effort) || found.effort
        const blocks = Array.isArray(message.content) ? (message.content as { type?: unknown; text?: unknown }[]) : []
        const said = blocks
          .filter(block => block.type === 'text')
          .map(block => text(block.text))
          .join(' ')
          .trim()
        if (said) found.lastReply = said
        break
      }
    }
  }

  return found
}

/** `ps -o pid=,lstart=` output, as pid to start time with its spacing evened out. */
export function parsePs(stdout: string): Map<number, string> {
  const started = new Map<number, string>()
  for (const line of stdout.split('\n')) {
    const found = /^\s*(\d+)\s+(.+?)\s*$/.exec(line)
    if (found) started.set(Number(found[1]), (found[2] ?? '').replace(/\s+/g, ' '))
  }

  return started
}

/** A record whose process is gone, or whose pid now belongs to a newer process, is not open. */
export function isAlive(started: ReadonlyMap<number, string>, record: Registered): boolean {
  const start = started.get(record.pid)
  if (start === undefined) return false

  return !record.procStart || start === record.procStart.replace(/\s+/g, ' ').trim()
}

export function modelLabel(id: string): string {
  const found = /(opus|sonnet|haiku|fable)[- ]?(\d+)(?:[-.](\d+))?/i.exec(id)
  if (!found) return id
  const [, family = '', major = '', minor] = found

  return `${family.charAt(0).toUpperCase()}${family.slice(1).toLowerCase()} ${major}${minor ? `.${minor}` : ''}`
}

/** What a session is waiting for, as the engine names it, in one word. */
const WAITING: Readonly<Record<string, string>> = {
  'permission prompt': 'permission',
  'sandbox request': 'permission',
  'worker request': 'permission',
  'goal proposal': 'permission',
  'input needed': 'question',
  'dialog open': 'dialog open',
}

export type RowInputs = {
  record: Registered
  transcript: Transcript | undefined
  beacon: Beacon | undefined
  /** When this hub saw the session go from working to idle, for one with no beacon. */
  seenTurnEnd: number
  /** When you last jumped to it or marked it seen. */
  seenAt: number
  thisSessionId: string
  now: number
}

/**
 * A session's row. Needs you: the engine says it is waiting. Your turn: it
 * finished a turn after you last typed there and you have not looked since.
 * Working, idle, and stale after three idle days.
 */
export function rowFor(inputs: RowInputs): HubRow {
  const { record, beacon, now } = inputs
  const said = inputs.transcript ?? EMPTY
  const project = record.cwd.split('/').filter(Boolean).pop() ?? record.cwd
  const title = said.customTitle || (record.nameSource === 'user' ? record.name : '') || said.aiTitle || record.name || project
  const isThis = record.sessionId === inputs.thisSessionId
  const turnEnd = beacon?.lastTurnEndAt || inputs.seenTurnEnd
  const isYourTurn = !isThis && turnEnd > 0 && turnEnd > Math.max(beacon?.lastInputAt ?? 0, inputs.seenAt)
  const engine = [modelLabel(said.model), said.effort].filter(Boolean).join(' · ')

  let group: Group
  let reason: string
  if (record.status === 'waiting') {
    group = 'needs'
    reason = WAITING[record.waitingFor ?? ''] ?? 'needs you'
  } else if (record.status === 'busy') {
    group = 'working'
    // What it last said is what it is doing; the group already says "working".
    reason = said.lastReply || 'working'
  } else if (record.status === 'shell') {
    group = 'working'
    reason = 'jobs running'
  } else if (isYourTurn) {
    group = 'turn'
    reason = said.lastReply ? `"${said.lastReply}"` : 'finished'
  } else {
    group = now - record.statusUpdatedAt > STALE_MS ? 'stale' : 'idle'
    reason = said.recap || 'idle'
  }

  return {
    sessionId: record.sessionId,
    title,
    project,
    branch: said.branch,
    group,
    reason: reason.replace(/\s+/g, ' ').trim(),
    engine,
    prompt: said.lastPrompt.replace(/\s+/g, ' ').trim(),
    since: record.statusUpdatedAt,
    isThis,
    isDesktop: record.entrypoint !== 'cli',
    cwd: record.cwd,
    pid: record.pid,
    focusUrl: beacon?.focusUrl ?? '',
  }
}

export const GROUPS: readonly Group[] = ['needs', 'turn', 'working', 'idle', 'stale']

/** Rows in queue order: the longest waiting first among those that need you, else the newest first. */
export function arrange(rows: readonly HubRow[]): HubRow[] {
  return [...rows].sort((a, b) => {
    const byGroup = GROUPS.indexOf(a.group) - GROUPS.indexOf(b.group)
    if (byGroup !== 0) return byGroup
    return a.group === 'needs' ? a.since - b.since : b.since - a.since
  })
}

export function countsOf(rows: readonly HubRow[]): HubCounts {
  const counts: HubCounts = { needs: 0, turn: 0, working: 0, idle: 0, stale: 0 }
  for (const row of rows) if (!row.isThis) counts[row.group] += 1

  return counts
}

/** `45s`, `12m`, `3h`, `4d`. */
export function age(ms: number): string {
  const seconds = Math.max(0, Math.round(ms / 1000))
  if (seconds < 60) return `${seconds}s`
  if (seconds < 3600) return `${Math.round(seconds / 60)}m`
  if (seconds < 86400) return `${Math.round(seconds / 3600)}h`

  return `${Math.round(seconds / 86400)}d`
}

export function clip(value: string, max: number): string {
  if (max <= 0) return ''
  return value.length <= max ? value : `${value.slice(0, Math.max(0, max - 1))}…`
}

/** The one-line summary under the prompt, or '' with nothing else open. */
export function statusLine(counts: HubCounts): string {
  const parts = [
    counts.needs && `${counts.needs} need${counts.needs === 1 ? 's' : ''} you`,
    counts.turn && `${counts.turn} your turn`,
    counts.working && `${counts.working} working`,
    counts.idle && `${counts.idle} idle`,
  ].filter(Boolean)

  return parts.length ? `sessions · ${parts.join(' · ')}` : ''
}

/** Where `/sessions new` starts: the path given (`~` expanded), else `fallback`. */
export function newSessionDir(args: string, home: string, fallback: string): string {
  const given = args.trim()
  if (!given) return fallback
  return given === '~' || given.startsWith('~/') ? `${home}${given.slice(1)}` : given
}

/** The Warp Tab Config the hub rewrites for each new session: one pane running `claude` in `dir`. */
export function tabConfig(dir: string): string {
  return [
    'name = "Claude session (session-hub)"',
    'title = "claude"',
    '',
    '[[panes]]',
    'id = "claude"',
    'type = "terminal"',
    `directory = ${JSON.stringify(dir)}`,
    'commands = ["claude"]',
    'is_focused = true',
    '',
  ].join('\n')
}

/** The Warp jump link in a process's environment, nothing else kept. */
export function focusUrlIn(environment: string): string {
  return /WARP_FOCUS_URL=(warp:\/\/session\/[0-9a-fA-F-]+)/.exec(environment)?.[1] ?? ''
}

