/** Where a session sits in the queue, most urgent first. */
export type Group = 'needs' | 'turn' | 'working' | 'idle' | 'stale'

/** One open session, as the Sessions section shows it. */
export type HubRow = {
  sessionId: string
  /** Its title: a custom title, a name you gave it, its AI title, else the derived name. */
  title: string
  /** The last folder of its working directory. */
  project: string
  branch: string
  group: Group
  /** Why it is in its group: "permission", "question", its last reply, its recap, "working". */
  reason: string
  /** Its model and effort, as `Opus 5.5 · high`, or ''. */
  engine: string
  /** The last prompt you gave it, or ''. */
  prompt: string
  /** When it entered its current state, ms since the epoch. */
  since: number
  isThis: boolean
  isDesktop: boolean
  cwd: string
  pid: number
  /** Its Warp jump link from its beacon, or '' when it has none yet. */
  focusUrl: string
}

/** The sessions in each group, this session left out: what Sprout and the status line read. */
export type HubCounts = { needs: number; turn: number; working: number; idle: number; stale: number }

declare module 'claude-code' {
  interface PluginState {
    'session-hub': {
      rows: HubRow[]
      counts: HubCounts
      showStale: boolean
      /** The minute, so ages redraw while nothing else changes. */
      minute: number
    }
  }
}
